<?php declare(strict_types=1);namespace App\Services;use App\Core\I18n;use App\Models\Menu;use App\Models\Page;use App\Models\Post;final class CmsService{public const BLOCK_TYPES=['heading','paragraph','html','list','quote','image','cta','columns','faq','code'];public static function renderBlocks(array $D,?string $S=null):string{$S=$S??I18n::locale();$Y='';foreach($D as $v){$j=$v['type']??'paragraph';$b=$v['data']??[];$c=fn(string $Z)=>I18n::pick($b[$Z]??'',$S);switch($j){case'heading':$g=min(4,max(2,(int)($b['level']??2)));$Y.="<h{$g} class=\"tp-cms-h\">".e($c('text'))."</h{$g}>";break;case'paragraph':$Y.='<p>'.nl2br(self::inline($c('text'))).'</p>';break;case'html':$Y.=self::sanitize($c('html'));break;case'list':$l=array_filter(array_map('trim',explode("\n",$c('items'))));$Y.='<ul class="tp-cms-list">'.implode('',array_map(fn($J)=>'<li>'.self::inline($J).'</li>',$l)).'</ul>';break;case'quote':$Y.='<blockquote class="tp-cms-quote">'.e($c('text')).($c('author')?'<cite>'.e($c('author')).'</cite>':'').'</blockquote>';break;case'image':$f=(string)($b['src']??'');if($f!==''&&(str_starts_with($f,'/')||preg_match('#^https?://#',$f))){$Y.='<figure class="tp-cms-figure"><img src="'.e($f).'" alt="'.e($c('alt')).'" loading="lazy">'.($c('caption')?'<figcaption>'.e($c('caption')).'</figcaption>':'').'</figure>';}break;case'cta':$U=(string)($b['href']??'#');$Y.='<p class="tp-cms-cta"><a class="tp-btn tp-btn--primary" href="'.e(self::safeUrl($U)).'">'.e($c('label')).'</a></p>';break;case'columns':$Y.='<div class="tp-grid tp-grid--2"><div>'.nl2br(self::inline($c('left'))).'</div><div>'.nl2br(self::inline($c('right'))).'</div></div>';break;case'faq':$Y.='<details class="tp-faq"><summary>'.e($c('question')).'</summary><div>'.nl2br(self::inline($c('answer'))).'</div></details>';break;case'code':$Y.='<pre class="tp-code"><code>'.e($c('code')).'</code></pre>';break;}}return $Y;}public static function inline(string $n):string{$m=e($n);$m=preg_replace('/\*\*(.+?)\*\*/s','<strong>$1</strong>',$m)??$m;$m=preg_replace('/(?<!\*)\*(?!\*)(.+?)\*/s','<em>$1</em>',$m)??$m;$m=preg_replace('/`([^`]+)`/','<code>$1</code>',$m)??$m;$m=preg_replace_callback('/\[([^\]]+)\]\(([^)\s]+)\)/',fn($l)=>'<a href="'.e(self::safeUrl(html_entity_decode($l[2]))).'">'.$l[1].'</a>',$m)??$m;return $m;}public static function safeUrl(string $b):string{$b=trim($b);if(preg_match('#^(https?:)?//#i',$b)||str_starts_with($b,'/')||str_starts_with($b,'#')||str_starts_with($b,'mailto:')){return $b;}return'#';}public static function sanitize(string $h):string{$S=['p','br','strong','em','b','i','u','s','a','ul','ol','li','h2','h3','h4','blockquote','code','pre','img','table','thead','tbody','tr','th','td','span','div','hr','figure','figcaption','small','sup','sub'];$h=preg_replace('/<(script|style|iframe|object|embed|form|input|textarea|button)\b[^>]*>.*?<\/\1>/is','',$h)??$h;$h=strip_tags($h,'<'.implode('><',$S).'>');$h=preg_replace_callback('/<([a-z0-9]+)([^>]*)>/i',function($I){$b=strtolower($I[1]);$d='';preg_match_all('/([a-z-]+)\s*=\s*("[^"]*"|\'[^\']*\')/i',$I[2],$n,PREG_SET_ORDER);foreach($n as $j){$u=strtolower($j[1]);$W=substr($j[2],1,-1);if(in_array($u,['href','src'],true)){$W=self::safeUrl(html_entity_decode($W));}elseif(!in_array($u,['alt','title','class','colspan','rowspan','loading'],true)){continue;}$d.=' '.$u.'="'.e($W).'"';}if($b==='a'){$d.=' rel="noopener"';}return'<'.$b.$d.'>';},$h)??$h;return $h;}public static function excerpt(array $o,int $c=160,?string $O=null):string{$e=trim(preg_replace('/\s+/',' ',strip_tags(self::renderBlocks($o,$O)))??'');return mb_strlen($e)>$c?mb_substr($e,0,$c-1).'…':$e;}public static function normalizeBlocks(mixed $q):array{if(is_string($q)){$q=json_decode($q,true);}if(!is_array($q)){return[];}$o=[];foreach($q as $e){if(!is_array($e)||!in_array($e['type']??'',self::BLOCK_TYPES,true)){continue;}$U=is_array($e['data']??null)?$e['data']:[];foreach($U as $i=>$l){if(is_array($l)){$U[$i]=array_filter(array_map(fn($Q)=>is_string($Q)?$Q:'',$l),fn($Q)=>$Q!=='');}}$o[]=['type'=>$e['type'],'data'=>$U];}return $o;}public static function menu(string $e):array{$W=[];foreach(Menu::items($e)as $G){$M=isset($G['key'])&&$G['key']!==''?t($G['key']):I18n::pick($G['label']??[]);$i=(string)($G['url']??'/');$W[]=['label'=>$M,'href'=>preg_match('#^https?://#',$i)?$i:url($i),'external'=>(bool)preg_match('#^https?://#',$i)];}return $W;}public static function pageUrl(array $e):string{$a=$e['slug'];return in_array($a,['legal','terms','privacy'],true)?url('/'.$a):url('/p/'.$a);}public static function postsForHome(int $X=3):array{return Post::published($X)['items'];}}